from typing import List
from collections import defaultdict

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        by_right = defaultdict(list)

        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            by_right[b].append((a, i))

        max1 = 0
        max2 = 0
        count1 = 0
        unique_idx = -1

        baseline = 0
        gain = [0] * len(conflictingPairs)

        for r in range(1, n + 1):
            for a, idx in by_right[r]:
                if a > max1:
                    max2 = max1
                    max1 = a
                    count1 = 1
                    unique_idx = idx
                elif a == max1:
                    count1 += 1
                    unique_idx = -1
                elif a > max2:
                    max2 = a

            baseline += r - max1

            if count1 == 1:
                gain[unique_idx] += max1 - max2

        return baseline + max(gain)
